/* Model bytes only. Book records, preferences and app runtime files are never removed. */
const ModelStorage=(()=>{
 const modelNames={m2m:'m2m100_418M',nllb:'nllb-200-distilled-600M'},languages=['jpn','jpn_vert','eng','kor'],presets=['fast','best'];
 const ocrKey=(preset,lang)=>`akai-beta-${preset}/${lang}.traineddata`;
 const names={jpn:'일본어 가로',jpn_vert:'일본어 세로',eng:'영어',kor:'한국어'},sizes={fast:{jpn:1.4,jpn_vert:1.9,eng:1.9,kor:1.1},best:{jpn:12,jpn_vert:12,eng:12,kor:11}};
 const catalog=[{id:'paddle',kind:'ocr-paddle',label:'PaddleOCR · 한·영·일',size:'약 60.8MB · 실행 파일 포함 · Apache-2.0'},{id:'m2m',kind:'translation',label:'M2M100',size:'약 650MB · MIT'},{id:'nllb',kind:'translation',label:'NLLB · 실험용 · 비상업',size:'약 900MB · CC-BY-NC-4.0 · 추후 제거 검토'},...presets.flatMap(p=>languages.map(lang=>({id:`ocr:${p}:${lang}`,kind:'ocr',preset:p,lang,label:`Tesseract · ${p==='fast'?'경량':'정밀'} · ${names[lang]}`,size:`약 ${sizes[p][lang]}MB · Tesseract · Apache-2.0`})) )];
 function ownsTranslation(url,engine){try{const u=new URL(url,location.href);return !!modelNames[engine]&&u.origin==='https://huggingface.co'&&u.pathname.split('/').includes(modelNames[engine])}catch{return false}}
 function ownsOcrUrl(url,preset,lang){try{const match=new URL(url,location.href).pathname.match(new RegExp('/models/ocr/'+preset+'/(jpn|jpn_vert|eng|kor)\\.traineddata\\.gz$'));return !!match&&(!lang||match[1]===lang)}catch{return false}}
 function parseOCR(id){const [kind,preset,lang]=id.split(':');if(kind!=='ocr'||!presets.includes(preset)||!languages.includes(lang))throw Error('관리 대상이 아닌 OCR 모델입니다.');return {preset,lang}}
 function validData(value){const a=value instanceof ArrayBuffer?new Uint8Array(value):ArrayBuffer.isView(value)?new Uint8Array(value.buffer,value.byteOffset,value.byteLength):null;if(!a||a.length<1024)return false;if(a[0]===31&&a[1]===139)return true;const count=new DataView(a.buffer,a.byteOffset,a.byteLength).getInt32(0,true);return count>0&&count<=256&&a.length>4+count*8}
 function openDb(create=false){return new Promise((resolve,reject)=>{if(!('indexedDB'in self)){create?reject(Error('이 브라우저는 모델 저장소를 사용할 수 없습니다.')):resolve(null);return}const req=indexedDB.open('keyval-store');req.onupgradeneeded=()=>{if(create)req.result.createObjectStore('keyval');else req.transaction.abort()};req.onsuccess=()=>{const db=req.result;if(db.objectStoreNames.contains('keyval'))resolve(db);else{db.close();create?reject(Error('OCR 저장소를 열 수 없습니다.')):resolve(null)}};req.onerror=()=>create?reject(req.error):resolve(null)})}
 async function readOCR(preset,lang){parseOCR(`ocr:${preset}:${lang}`);const db=await openDb();if(!db)return null;return new Promise((resolve,reject)=>{const tx=db.transaction('keyval','readonly'),req=tx.objectStore('keyval').get(ocrKey(preset,lang));let value=null;req.onsuccess=()=>value=req.result;tx.oncomplete=()=>{db.close();resolve(validData(value)?value:null)};tx.onerror=()=>{db.close();reject(tx.error)}})}
 async function writeOCR(preset,lang,data){parseOCR(`ocr:${preset}:${lang}`);if(!validData(data))throw Error('올바른 OCR 모델 파일이 아닙니다. 다시 다운로드하세요.');const db=await openDb(true);return new Promise((resolve,reject)=>{const tx=db.transaction('keyval','readwrite');tx.objectStore('keyval').put(data,ocrKey(preset,lang));tx.oncomplete=()=>{db.close();resolve()};tx.onerror=tx.onabort=()=>{db.close();reject(tx.error||Error('모델 저장 공간이 부족합니다.'))}})}
 async function removeOCR(preset,lang){const db=await openDb();if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('keyval','readwrite');tx.objectStore('keyval').delete(ocrKey(preset,lang));tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}});await cachedFiles(u=>ownsOcrUrl(u,preset,lang),true)}
 async function cachedFiles(test,remove=false){let count=0,bytes=0,unknown=0,urls=[];if(!('caches'in self))return {count,bytes,unknown,urls};for(const name of await caches.keys()){if(name!=='transformers-cache'&&!name.startsWith('akai-beta-'))continue;const cache=await caches.open(name);for(const req of await cache.keys()){if(!test(req.url))continue;count++;urls.push(req.url);if(remove){await cache.delete(req);continue}const res=await cache.match(req),size=Number(res?.headers.get('content-length'));if(size>0)bytes+=size;else unknown++}}return {count,bytes,unknown,urls}}
 async function status(id){if(id==='paddle')return PaddleModels.status();if(modelNames[id]){const r=await cachedFiles(u=>ownsTranslation(u,id)),paths=r.urls.map(u=>new URL(u).pathname);const ready=['config.json','tokenizer.json','tokenizer_config.json'].every(f=>paths.some(p=>p.endsWith('/'+f)))&&paths.some(p=>/\/encoder_model[^/]*\.onnx$/.test(p))&&paths.some(p=>/\/decoder_model_merged[^/]*\.onnx$/.test(p));return {id,...r,ready,state:ready?'사용 가능':r.count?'일부 파일만 저장됨':'미준비'}}const {preset,lang}=parseOCR(id),data=await readOCR(preset,lang),r=await cachedFiles(u=>ownsOcrUrl(u,preset,lang));return {id,ready:!!data,count:data?1:r.count,bytes:data?.byteLength||r.bytes,unknown:data?0:r.unknown,state:data?'사용 가능':r.count?'준비 필요':'미준비'}}
 async function list(){return Promise.all(catalog.map(async r=>({...r,...await status(r.id)})))}
 async function remove(id){if(id==='paddle'){await PaddleModels.remove();return}if(id==='all'){await PaddleModels.remove();for(const engine of Object.keys(modelNames))await remove(engine);for(const p of presets)for(const l of languages)await removeOCR(p,l);return}if(modelNames[id])await cachedFiles(u=>ownsTranslation(u,id),true);else if(presets.includes(id)){for(const lang of languages)await removeOCR(id,lang)}else{const {preset,lang}=parseOCR(id);await removeOCR(preset,lang)}}
 async function legacyFastCount(){let count=0;for(const lang of languages)if(await readOCR('fast',lang))count++;return count}
 return {legacyFastCount,catalog,list,status,readOCR,writeOCR,remove,validData,ownsTranslation,ownsOcrUrl,ocrKey,parseOCR};
})();
